-- -------------------------------------------------------------------------
-- Change log.
-- -------------------------------------------------------------------------
CREATE TABLE archtics._change_log (
    change_log_id   BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    table_name      VARCHAR(63)  NOT NULL,
    operation       CHAR(1)      NOT NULL CHECK (operation IN ('I', 'U', 'D')),
    -- Text, not BIGINT: one log serves tables keyed by integer, bigint and
    -- composite business keys alike.
    row_key         VARCHAR(200) NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    changed_by      TEXT         NOT NULL DEFAULT current_user,
    -- Populated on delete only. Inserts and updates leave it null because
    -- the current row remains readable in the base table, and copying it
    -- would double the write volume of the busiest tables.
    old_row         JSONB
);

CREATE INDEX ix_archtics_change_log_changed_at
    ON archtics._change_log (changed_at);
CREATE INDEX ix_archtics_change_log_table
    ON archtics._change_log (table_name, changed_at);

COMMENT ON TABLE archtics._change_log IS
    'Change capture for incremental extraction. Deletes are the reason this '
    'exists: a high-water-mark read of updated_at cannot see a removed row.';

CREATE OR REPLACE FUNCTION archtics.log_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    -- TG_ARGV[0] names the key column, so one function serves every table.
    key_column TEXT := TG_ARGV[0];
    source_row JSONB;
BEGIN
    source_row := to_jsonb(COALESCE(OLD, NEW));

    INSERT INTO archtics._change_log (table_name, operation, row_key, old_row)
    VALUES (
        TG_TABLE_NAME,
        CASE TG_OP WHEN 'INSERT' THEN 'I' WHEN 'UPDATE' THEN 'U' ELSE 'D' END,
        COALESCE(source_row ->> key_column, '(unknown)'),
        CASE WHEN TG_OP = 'DELETE' THEN source_row ELSE NULL END
    );

    RETURN COALESCE(NEW, OLD);
END;
$$;

COMMENT ON FUNCTION archtics.log_change() IS
    'Generic change logger. Pass the key column name as the trigger argument.';

-- Applied to the master and financial tables, where a missed delete would
-- leave an orphan in the target model. Deliberately not applied to
-- append-only high-volume tables: the write volume would double for no
-- benefit, since nothing ever deletes from them.
CREATE TRIGGER trg_building_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.building
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('building_id');
CREATE TRIGGER trg_seat_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.seat
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('seat_id');
CREATE TRIGGER trg_manifest_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.manifest
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('manifest_id');
CREATE TRIGGER trg_event_manifest_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.event_manifest
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('event_manifest_id');
CREATE TRIGGER trg_sta_account_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.sta_account
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('sta_account_id');
CREATE TRIGGER trg_account_seat_assignment_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.account_seat_assignment
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('account_seat_assignment_id');
CREATE TRIGGER trg_psl_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.psl
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('psl_id');
CREATE TRIGGER trg_suite_lease_change
    AFTER INSERT OR UPDATE OR DELETE ON archtics.suite_lease
    FOR EACH ROW EXECUTE FUNCTION archtics.log_change('suite_lease_id');

-- -------------------------------------------------------------------------
-- Role separation.
--
-- The roles are created defensively because every schema grants to the same
-- three and the load order across schemas is not guaranteed.
-- -------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_app') THEN
        CREATE ROLE offball_app NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_analyst') THEN
        CREATE ROLE offball_analyst NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_ingest') THEN
        CREATE ROLE offball_ingest NOLOGIN;
    END IF;
END;
$$;

GRANT USAGE ON SCHEMA archtics TO offball_app, offball_analyst, offball_ingest;

-- The application needs everything.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA archtics
    TO offball_app;

-- Analysts and the ingestion job read.
GRANT SELECT ON ALL TABLES IN SCHEMA archtics
    TO offball_analyst, offball_ingest;

COMMENT ON SCHEMA archtics IS
    'Archtics -- seating manifest, physical seat inventory and '
    'season-ticket administration. Authoritative for seat existence and '
    'capacity; TM/AXS mirrors availability. Extract pattern: CDC log.';
